// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Library: none — native interpolate/spring for choreographed multi-step timeline

const { fontFamily: interFamily } = loadInter();



export type MalloyGridProps = Record<string, any>;

const IconSvg: React.FC<{ index: number; color: string; size: number; strokeWidth: number }> = ({ index, color, size, strokeWidth }) => {
  const commonProps = {
    fill: "none",
    stroke: color,
    strokeWidth,
    strokeLinecap: "round" as const,
    strokeLinejoin: "round" as const,
    style: { transition: "none" }
  };

  switch (index) {
    case 0: // Play
      return (
        <svg width={size} height={size} viewBox="0 0 100 100" style={{ transition: "none" }}>
          <circle cx="50" cy="50" r="40" {...commonProps} />
          <polygon points="40,30 40,70 70,50" {...commonProps} />
        </svg>
      );
    case 1: // Image
      return (
        <svg width={size} height={size} viewBox="0 0 100 100" style={{ transition: "none" }}>
          <rect x="10" y="20" width="80" height="60" rx="6" {...commonProps} />
          <circle cx="70" cy="40" r="8" {...commonProps} />
          <polyline points="10,80 40,50 60,70 80,45 90,55" {...commonProps} />
        </svg>
      );
    case 2: // Chart
      return (
        <svg width={size} height={size} viewBox="0 0 100 100" style={{ transition: "none" }}>
          <line x1="10" y1="85" x2="90" y2="85" {...commonProps} />
          <rect x="20" y="55" width="15" height="30" {...commonProps} />
          <rect x="45" y="35" width="15" height="50" {...commonProps} />
          <rect x="70" y="15" width="15" height="70" {...commonProps} />
        </svg>
      );
    case 3: // User
      return (
        <svg width={size} height={size} viewBox="0 0 100 100" style={{ transition: "none" }}>
          <circle cx="50" cy="35" r="20" {...commonProps} />
          <path d="M 20 90 C 20 60 80 60 80 90" {...commonProps} />
          <circle cx="50" cy="50" r="45" {...commonProps} />
        </svg>
      );
    case 4: // Center icon (covered mostly)
      return (
        <svg width={size} height={size} viewBox="0 0 100 100" style={{ transition: "none" }}>
          <circle cx="50" cy="50" r="30" {...commonProps} />
        </svg>
      );
    case 5: // Bag
      return (
        <svg width={size} height={size} viewBox="0 0 100 100" style={{ transition: "none" }}>
          <rect x="20" y="40" width="60" height="50" rx="4" {...commonProps} />
          <path d="M 35 40 v -10 a 15 15 0 0 1 30 0 v 10" {...commonProps} />
        </svg>
      );
    case 6: // Megaphone
      return (
        <svg width={size} height={size} viewBox="0 0 100 100" style={{ transition: "none" }}>
          <polygon points="20,40 55,20 55,80 20,60" {...commonProps} />
          <rect x="35" y="70" width="10" height="20" rx="2" {...commonProps} />
          <path d="M 70 30 Q 85 50 70 70" {...commonProps} />
          <path d="M 80 20 Q 100 50 80 80" {...commonProps} />
        </svg>
      );
    case 7: // Chat
      return (
        <svg width={size} height={size} viewBox="0 0 100 100" style={{ transition: "none" }}>
          <path d="M 15 25 h 70 v 40 h -30 l -15 15 v -15 h -25 z" {...commonProps} />
          <circle cx="35" cy="45" r="3" fill={color} stroke="none" style={{ transition: "none" }} />
          <circle cx="50" cy="45" r="3" fill={color} stroke="none" style={{ transition: "none" }} />
          <circle cx="65" cy="45" r="3" fill={color} stroke="none" style={{ transition: "none" }} />
        </svg>
      );
    case 8: // Heart
      return (
        <svg width={size} height={size} viewBox="0 0 100 100" style={{ transition: "none" }}>
          <path d="M 50 85 C 50 85 15 55 15 35 C 15 20 35 15 50 30 C 65 15 85 20 85 35 C 85 55 50 85 50 85 Z" {...commonProps} />
        </svg>
      );
    default:
      return null;
  }
};

const MalloyGrid: React.FC<MalloyGridProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 8,
  primaryColor = "#e5b879", // Gold
  textColor = "#ffffff", // White
  calloutText = "EVERY FRAME → SPONSORED",
  chipText = "SPONSORED",
  taglineText = "MALLOY STUDIO",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timeline Constants (Frames based on 60fps)
  const gridEntranceStart = 5;
  const gridEntranceStagger = 3;
  const waveStart = 45;
  const waveStagger = 8;
  const dimStart = 140;
  const calloutStart = 145;
  const calloutExitStart = 260;
  const undimStart = 265;
  const pulseStart = 310;
  const taglineStart = 350;

  // Layout Constants
  const cardW = 460 * s;
  const cardH = 260 * s;
  const gap = 30 * s;
  const cornerRadius = 16 * s;
  const borderWidth = 4 * s;

  // Dimming Overlay Logic
  const gridOpacityBase = interpolate(frame, 
    [dimStart, dimStart + 15, undimStart, undimStart + 15], 
    [1, 0.25, 0.25, 1], 
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, fontWeight: 900, overflow: "hidden", alignItems: "center", justifyContent: "center", transition: "none" }}>
      
      {/* 3x3 Grid */}
      <div style={{
        display: "flex",
        flexWrap: "wrap",
        width: (cardW * 3) + (gap * 2),
        gap: gap,
        justifyContent: "center",
        alignItems: "center",
        opacity: gridOpacityBase,
        transition: "none",
        position: "relative"
      }}>
        {Array.from({ length: 9 }).map((_, i) => {
          const row = Math.floor(i / 3);
          const col = i % 3;
          const waveIndex = row + col;

          // Animations per card
          const entranceDelay = gridEntranceStart + waveIndex * gridEntranceStagger;
          const scaleIn = spring({
            frame: frame - entranceDelay,
            fps,
            config: { damping: 14, stiffness: 120 }
          });

          const waveDelay = waveStart + waveIndex * waveStagger;
          const borderDrawProgress = spring({
            frame: frame - waveDelay,
            fps,
            config: { damping: 16, stiffness: 80 }
          });

          const chipFlyProgress = spring({
            frame: frame - waveDelay - 6,
            fps,
            config: { damping: 10, mass: 0.7, stiffness: 100 }
          });

          const globalPulseProgress = interpolate(
            frame,
            [pulseStart, pulseStart + 8, pulseStart + 16],
            [0, 1, 0],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          // Derived values
          const isCardVisible = frame >= entranceDelay;
          const isGoldVisible = frame >= waveDelay;
          
          const chipX = interpolate(chipFlyProgress, [0, 1], [-cardW * 0.5, 16 * s], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
          const chipScale = interpolate(globalPulseProgress, [0, 1], [1, 1.15]);

          return (
            <div key={i} style={{
              width: cardW,
              height: cardH,
              position: "relative",
              opacity: isCardVisible ? 1 : 0,
              transform: `scale(${isCardVisible ? Math.max(0, scaleIn) : 0})`,
              transition: "none",
              display: "flex",
              alignItems: "center",
              justifyContent: "center"
            }}>
              
              {/* Base White Border */}
              <svg width={cardW} height={cardH} viewBox={`0 0 ${cardW} ${cardH}`} style={{ position: "absolute", inset: 0, transition: "none" }}>
                <rect 
                  x={borderWidth/2} y={borderWidth/2} 
                  width={cardW - borderWidth} height={cardH - borderWidth} 
                  rx={cornerRadius} 
                  fill="none" stroke={textColor} strokeWidth={borderWidth} 
                  style={{ transition: "none" }}
                />
              </svg>

              {/* Drawing Gold Border */}
              {isGoldVisible && (
                <svg width={cardW} height={cardH} viewBox={`0 0 ${cardW} ${cardH}`} style={{ position: "absolute", inset: 0, transition: "none" }}>
                  <rect 
                    x={borderWidth/2} y={borderWidth/2} 
                    width={cardW - borderWidth} height={cardH - borderWidth} 
                    rx={cornerRadius} 
                    fill="none" stroke={primaryColor} strokeWidth={borderWidth}
                    pathLength={1}
                    strokeDasharray={1}
                    strokeDashoffset={1 - Math.max(0, Math.min(1, borderDrawProgress))}
                    style={{ transition: "none" }}
                  />
                </svg>
              )}

              {/* Central Icon */}
              <div style={{ transform: "scale(1.2)", transition: "none" }}>
                 <IconSvg index={i} color={isGoldVisible && borderDrawProgress > 0.5 ? primaryColor : textColor} size={80 * s} strokeWidth={6 * s} />
              </div>

              {/* SPONSORED Chip */}
              {isGoldVisible && frame >= waveDelay + 6 && (
                <div style={{
                  position: "absolute",
                  bottom: 16 * s,
                  left: 0, // Driven by transform
                  backgroundColor: primaryColor,
                  color: "#000000",
                  padding: `${6 * s}px ${12 * s}px`,
                  borderRadius: 6 * s,
                  fontSize: 18 * s,
                  letterSpacing: 1 * s,
                  transform: `translateX(${chipX}px) scale(${chipScale})`,
                  transition: "none",
                  whiteSpace: "nowrap"
                }}>
                  {chipText}
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* Center Callout */}
      {frame >= calloutStart && (
        <div style={{
          position: "absolute",
          top: "50%",
          left: "50%",
          backgroundColor: primaryColor,
          color: "#000000",
          padding: `${30 * s}px ${60 * s}px`,
          fontSize: 72 * s,
          letterSpacing: -1 * s,
          whiteSpace: "nowrap",
          transform: `translate(-50%, -50%) scale(${
             frame < calloutExitStart 
               ? Math.max(0, spring({ frame: frame - calloutStart, fps, config: { damping: 14 } }))
               : interpolate(spring({ frame: frame - calloutExitStart, fps, config: { damping: 16 } }), [0, 1], [1, 0])
          })`,
          opacity: frame >= calloutExitStart + 15 ? 0 : 1, // Ensure fully unmounted visually after exit
          transition: "none",
          boxShadow: `0 ${10 * s}px ${30 * s}px rgba(0,0,0,0.5)`
        }}>
          {calloutText}
        </div>
      )}

      {/* Tagline */}
      <div style={{
        position: "absolute",
        bottom: 60 * s,
        color: textColor,
        fontSize: 36 * s,
        letterSpacing: 2 * s,
        textAlign: "center",
        width: "100%",
        transition: "none"
      }}>
        {taglineText.substring(
          0, 
          Math.floor(interpolate(frame, [taglineStart, taglineStart + 30], [0, taglineText.length], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }))
        )}
      </div>

    </AbsoluteFill>
  );
};

export default MalloyGrid;